SELECT * FROM proj_project WHERE id IN
#{id}
AND deleted = b'0' ORDER BY id FOR UPDATE

mapper.update:
UPDATE proj_project
SET version = version + 1
WHERE id = #{projectId}
  AND version = #{expectedVersion}
  AND deleted = b'0'

UPDATE proj_project
SET assignment_status = #{query.assignmentStatus}
WHERE id = #{query.projectId}
  AND version = #{query.version}
  AND deleted = b'0'

UPDATE proj_project
SET signing_method = #{query.signingMethod},
    project_category = #{query.projectCategory},
    implementation_mode = #{query.implementationMode},
    major_project_level = #{query.majorProjectLevel},
    version = version + 1
WHERE id = #{query.projectId}
  AND tenant_id = #{query.tenantId}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE proj_project
SET current_stage = #{query.currentStage},
    lifecycle_status = #{query.lifecycleStatus},
    assignment_status = #{query.assignmentStatus},
    version = version + 1,
    updater = #{query.updater},
    update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.projectId}
  AND version = #{query.expectedVersion}
  AND lifecycle_status = #{query.expectedLifecycleStatus}
  AND deleted = b'0'

UPDATE proj_project
SET current_stage = #{query.targetStage}, version = version + 1,
    updater = #{query.updater}, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{query.tenantId} AND id = #{query.projectId}
  AND version = #{query.expectedVersion} AND current_stage = #{query.expectedCurrentStage}
  AND lifecycle_status = 'ACTIVE' AND deleted = b'0'

mapper.select:
SELECT p.*
FROM proj_project p
WHERE p.tenant_id = #{query.tenantId}
  AND p.deleted = b'0'
  AND p.id IN

      #{projectId}


      AND p.project_name LIKE CONCAT('%', #{query.projectNameKeyword}, '%')


      AND p.project_code LIKE CONCAT(#{query.projectCodePrefix}, '%')



          AND p.current_stage = #{query.status}
          AND p.lifecycle_status = 'ACTIVE'



              AND p.lifecycle_status = #{query.status}




      AND p.signing_method = #{query.signingMethod}


      AND p.project_category = #{query.projectCategory}


      AND p.implementation_mode = #{query.implementationMode}


      AND p.major_project_level = #{query.majorProjectLevel}


      AND p.contract_no LIKE CONCAT('%', #{query.contractNoKeyword}, '%')


      AND p.department_id = #{query.departmentId}


      AND p.company_id = #{query.companyId}


      AND p.create_time >= #{query.createTimeStart}


      AND p.create_time < #{query.createTimeEnd}


      AND p.project_close_time >= #{query.closeTimeStart}


      AND p.project_close_time < #{query.closeTimeEnd}


      AND p.project_refresh_time >= #{query.refreshTimeStart}


      AND p.project_refresh_time < #{query.refreshTimeEnd}


      AND EXISTS (
          SELECT 1 FROM proj_project_party pp
          WHERE pp.project_id = p.id
            AND pp.tenant_id = #{query.tenantId}
            AND pp.deleted = b'0'
            AND pp.status = 'ACTIVE'
            AND (pp.effective_from IS NULL OR pp.effective_from <= #{query.effectiveAt})
            AND (pp.effective_to IS NULL OR pp.effective_to > #{query.effectiveAt})
            AND pp.party_role IN ('AGENT', 'SERVICE_PROVIDER')
            AND (pp.party_name LIKE CONCAT('%', #{query.agentServiceProviderKeyword}, '%')
              OR pp.party_code LIKE CONCAT('%', #{query.agentServiceProviderKeyword}, '%'))
      )

ORDER BY p.id DESC
